        "image": "",
        "title": "Recommended Hardware",
        "number": "01",
        "caption": "Recommended Hardware",
        "image_url": "",
        "recommendedProductSlug": "mall-inline-badgeasus-rog-ergo-monitor-arm-aas01-cable-management-ergonomic-supports-up-to-39-monitors-and-vesa-100-x-100mm"
